#include <stdio.h>

int collatz_steps(int n) {
    int steps = 0;
    while (n != 1) {
        n = (n % 2 == 0) ? n / 2 : 3 * n + 1;
        steps++;
    }
    return steps;
}

int main() {
    printf("%d\n", collatz_steps(7));
    return 0;
}
